import openpyxl
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)
ws=wb['Answer']
print('data validations:', len(ws.data_validations.dataValidation) if ws.data_validations else 0)
if ws.data_validations:
    for dv in ws.data_validations.dataValidation:
        print('dv', dv.type, dv.formula1, 'sqref', dv.sqref)
print('conditional formatting:', len(ws.conditional_formatting))
# openpyxl's conditional_formatting is dict-like
for key in ws.conditional_formatting:
    print('cf range', key)
    rules=ws.conditional_formatting[key]
    for r in rules:
        print(' ', r.type, getattr(r,'formula',None))
