    for c in range(1,12):
        cell=ws.cell(r,c)
        if is_interesting(cell):
            interesting.append(cell)

print('interesting count',len(interesting))
# Print cells with empty value but with border/fill etc
for cell in interesting:
    if cell.value in (None,''):
        coord=cell.coordinate
        fill=cell.fill.fgColor.rgb if cell.fill and cell.fill.fgColor else None
        border_styles=(cell.border.left.style,cell.border.right.style,cell.border.top.style,cell.border.bottom.style) if cell.border else None
        nf=cell.number_format
        print(coord,'empty','fill',fill,'border',border_styles,'numfmt',nf)
