import openpyxl
from openpyxl.styles.fills import PatternFill
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)
ws=wb['Answer']
# Identify cells with border or fill or number format different from 'General'
def is_interesting(cell):
    if cell.value not in (None,''):
        return True
    if cell.fill and cell.fill.patternType is not None and cell.fill.patternType!='none':
        return True
    if cell.border and any(getattr(cell.border,side).style is not None for side in ['left','right','top','bottom']):
        return True
    if cell.number_format not in (None,'General'):
        return True
    if cell.font and (cell.font.bold or cell.font.italic or cell.font.color is not None):
        # but many fonts; keep
        return True
    return False

interesting=[]
for r in range(1,25):
    for c in range(1,12):
        cell=ws.cell(r,c)
        if is_interesting(cell):
            interesting.append(cell)

print('interesting count',len(interesting))
# Print cells with empty value but with border/fill etc
for cell in interesting:
    if cell.value in (None,''):
        coord=cell.coordinate
        fill=cell.fill.fgColor.rgb if cell.fill and cell.fill.fgColor else None
        border_styles=(cell.border.left.style,cell.border.right.style,cell.border.top.style,cell.border.bottom.style) if cell.border else None
        nf=cell.number_format
        print(coord,'empty','fill',fill,'border',border_styles,'numfmt',nf)
